import pandas as pd
import random
from sklearn.model_selection import train_test_split
import math


def task_func(n_data_points=10000, min_value=0.0, max_value=10.0, test_size=0.2):
    """
    Generate random floating-point numbers in the given range, truncate them to
    3 decimal places, and split the data into train and test sets.

    Returns:
        tuple[pd.DataFrame, pd.DataFrame]: (train_set, test_set)
    """
    if n_data_points < 0:
        raise ValueError("n_data_points must be non-negative.")
    if not isinstance(test_size, (int, float)):
        raise TypeError("test_size must be a number.")
    if test_size < 0 or test_size > 1:
        raise ValueError("test_size must be between 0 and 1 inclusive.")

    low, high = (min_value, max_value) if min_value <= max_value else (max_value, min_value)

    def truncate_to_3_decimals(value):
        return math.trunc(value * 1000) / 1000.0

    values = [truncate_to_3_decimals(random.uniform(low, high)) for _ in range(n_data_points)]
    data = pd.DataFrame({"Value": values})

    if n_data_points == 0:
        empty = pd.DataFrame(columns=["Value"])
        return empty.copy(), empty.copy()

    if test_size == 0:
        return data.reset_index(drop=True), pd.DataFrame(columns=["Value"])
    if test_size == 1:
        return pd.DataFrame(columns=["Value"]), data.reset_index(drop=True)

    # Use train_test_split while avoiding invalid splits for small datasets.
    test_count = int(round(n_data_points * test_size))

    if n_data_points == 1:
        if test_count >= 1:
            return pd.DataFrame(columns=["Value"]), data.reset_index(drop=True)
        return data.reset_index(drop=True), pd.DataFrame(columns=["Value"])

    test_count = max(1, min(n_data_points - 1, test_count))

    train_set, test_set = train_test_split(data, test_size=test_count, shuffle=True)
    return train_set.reset_index(drop=True), test_set.reset_index(drop=True)
